SELECT 'состояния задач ' || fact_gap($1, 'task-state') || ': сходится ли документ с историей — неизвестно, а не «сходится»' AS detail WHERE NOT fact_fresh($1, 'task-state') UNION ALL SELECT t.id || ' — документ говорит «' || btrim(f.value) || '», история говорит «' || coalesce(s.state, 'not_started') || '»'   FROM project_plan_tasks t   JOIN project_document_fields f ON f.project_id = t.project_id AND f.entity_kind = t.entity_kind    AND f.entity_name = t.entity_name AND f.name = 'Состояние' AND btrim(f.value) <> ''   LEFT JOIN task_state s ON s.project_id = t.project_id AND s.task_id = t.id  WHERE t.project_id = $1 AND t.entity_kind <> ''    AND (CASE WHEN f.value ILIKE '%закрыт%' THEN 'closed' ELSE 'not_started' END) <> coalesce(s.state, 'not_started')  ORDER BY 1
